import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { login } from "../../redux/auth/authSlice";
import { useNavigate, Link } from "react-router-dom";
import { setAuthToken } from "../../redux/root/api";

const Login = () => {
  const [form, setForm] = useState({ username: "", password: "" });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const res = await dispatch(login(form));
      if (res.meta.requestStatus === "fulfilled") {
        const { token, username, roles } = res.payload;
        // ✅ مطمئن شویم توکن در localStorage ذخیره شده
        localStorage.setItem("token", token);
        localStorage.setItem("username", username);
        localStorage.setItem("roles", JSON.stringify(roles || []));
        // ✅ تنظیم توکن برای axios
        setAuthToken(token);
        console.log("Login successful - Token:", token);
        console.log("User roles:", roles);
        // اگر کاربر ادمین است، به صفحه کاربران هدایت شود
        if (roles && roles.includes("ROLE_ADMIN")) {
          navigate("/users");
        } else {
          // اگر کاربر معمولی است، به صفحه کارمندان هدایت شود
          navigate("/");
        }

        // صفحه را ریلود کن تا تغییرات اعمال شود
        window.location.reload();
      } else {
        setError("Invalid username or password");
      }
    } catch (err) {
      setError("Login failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container-fluid d-flex justify-content-center align-items-center min-vh-100">
      <div className="card shadow" style={{ width: "100%", maxWidth: "400px" }}>
        <div className="card-body p-4">
          <h3 className="card-title text-center mb-4">Login</h3>

          {error && (
            <div className="alert alert-danger" role="alert">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="mb-3">
              <input
                id="username"
                className="form-control form-control-lg"
                placeholder="Enter username"
                value={form.username}
                onChange={(e) => setForm({ ...form, username: e.target.value })}
                required
              />
            </div>

            <div className="mb-3">
              <input
                id="password"
                className="form-control form-control-lg"
                type="password"
                placeholder="Enter password"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                required
              />
            </div>

            <button
              className="btn btn-primary btn-lg w-100 mb-3"
              type="submit"
              disabled={loading}
            >
              {loading ? (
                <>
                  <span
                    className="spinner-border spinner-border-sm me-2"
                    role="status"
                    aria-hidden="true"
                  ></span>
                  Logging in...
                </>
              ) : (
                "Login"
              )}
            </button>

            <div className="text-center">
              <p className="mb-0">
                Don't have an account?{" "}
                <Link to="/signup" className="text-decoration-none">
                  Sign up
                </Link>
              </p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;
